package app.localmind.assistant.domain.cloud

import app.localmind.assistant.domain.inference.GenerationEvent
import app.localmind.assistant.domain.inference.GenerationRequest
import kotlinx.coroutines.flow.Flow

/**
 * Extensible cloud provider abstraction. Disabled by default ("NEVER_USE_CLOUD").
 * Responses generated by a CloudModelProvider must always be visibly labeled in the UI.
 */
interface CloudModelProvider {
    val providerId: String
    suspend fun listModels(): List<RemoteModel>
    fun generate(request: GenerationRequest): Flow<GenerationEvent>
    suspend fun validateConfiguration(): ProviderStatus
}

data class RemoteModel(
    val id: String,
    val displayName: String,
    val providerId: String,
    val contextWindow: Int
)

enum class CloudRoutingPolicy {
    NEVER_USE_CLOUD,
    ASK_EVERY_TIME,
    ALLOW_ONLY_SELECTED_PERSONAS,
    MANUAL_CLOUD_SELECTION
}

sealed interface ProviderStatus {
    data object Unconfigured : ProviderStatus
    data object Ready : ProviderStatus
    data class InvalidConfiguration(val reason: String) : ProviderStatus
}
